const Metro = require('metro');
const { getDefaultConfig } = require('expo/metro-config');
const config = getDefaultConfig(__dirname);
config.watcher = config.watcher || {};
config.watcher.watchman = false;
config.resolver = config.resolver || {};
config.resolver.useWatchman = false;
config.server = config.server || {};
config.server.watchman = false;
Metro.runBuild(config, {
  entry: 'node_modules/expo-router/entry.js',
  out: 'android/app/build/generated/assets/createBundleQaJsAndAssets/index.android.bundle',
  platform: 'android',
  dev: false,
  minify: true,
}).then(() => {
  console.log('BUNDLE_SUCCESS');
  process.exit(0);
}).catch((err) => {
  console.error('BUNDLE_ERROR:', err.message);
  process.exit(1);
});
" > /tmp/metro_bundle.log 2>&1 &
BUNDLE_PID=$!
echo "Bundle PID: $BUNDLE_PID"
for i in $(seq 1 11); do
  sleep 5
  if kill -0 $BUNDLE_PID 2>/dev/null; then
    last=$(tail -1 /tmp/metro_bundle.log 2>/dev/null | head -c 200)
    echo "[$i] running: $last"
  else
    echo "[$i] exited"
    tail -5 /tmp/metro_bundle.log
    if [ -f android/app/build/generated/assets/createBundleQaJsAndAssets/index.android.bundle ]; then
      size=$(stat -c%s android/app/build/generated/assets/createBundleQaJsAndAssets/index.android.bundle)
      echo "Bundle size: $size"
    fi
    break
  fi
done

